rules:
@media (prefers-reduced-motion: reduce) {
  .page-in, .route-in, .stagger > *, .sheet-in { animation: 200ms ease 0s 1 normal both running v2-fade !important; }
  .press:active, .drop-hot, .drop-hot .folder-lift { transform: none !important; }
  .scan::after { animation: auto ease 0s 1 normal none running none; }
  .icon-swap { animation: auto ease 0s 1 normal none running none; }
  .link-fill { transition: none; }
  ::view-transition-old(root), ::view-transition-new(root) { animation: auto ease 0s 1 normal none running none; }
}

@media (prefers-reduced-motion: reduce) {
  .review-flipbook *, .animate-spin, .animate-shimmer { animation: auto ease 0s 1 normal none running none !important; }
  .motion-toggle { display: none; }
  .progress-fill { transition: none; }
}

@media (prefers-reduced-motion: reduce) {
  .kanban-art * { animation: auto ease 0s 1 normal none running none !important; }
  .kanban-motion { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .review-robot-dance, .review-analysis-scan, .review-progress-activity, .review-step-text { animation: auto ease 0s 1 normal none running none; }
  .review-progress-fill, .review-frame-grid, .review-frame-target { transition: none; }
  .request-motion { display: none; }
}
